type ModuleKey = "overview" | "payments" | "treasury" | "markets" | "compliance" | "reports" | "sandbox" | "registry" | "integrations" | "governance" | "alerts";

const moduleMeta: Record<ModuleKey, { number: string; title: string; subtitle: string }> = {
  overview: { number: "00", title: "Operating posture", subtitle: "A source-honest view of configured control-plane records across Nigeria (NGN), Kenya (KES), and South Africa (ZAR)." },
  payments: { number: "01", title: "Payment orchestration", subtitle: "Draft and inspect cross-border payment orders. Execution remains blocked until a verified policy decision and provider finality exist." },
  treasury: { number: "02", title: "Treasury & liquidity", subtitle: "Record reconciled liquidity, nostro, vostro, pre-funding, and custody positions with attributable source evidence." },
  markets: { number: "03", title: "FX & stablecoin evidence", subtitle: "Ingest only source-stamped NGN, KES, ZAR, USDC, and USDT observations from verified active integrations." },
  compliance: { number: "04", title: "Compliance operations", subtitle: "Track KYC, sanctions, transaction-monitoring, Travel Rule, counterparty, and SAR/STR cases with clear disposition evidence." },
  reports: { number: "05", title: "CBN · CBK · SARB reporting", subtitle: "Create reviewed report packs. Submission status is never represented as complete without a verified submission channel and reference." },
  sandbox: { number: "06", title: "CBN Sandbox readiness", subtitle: "Record Cohort 2 application evidence and controlled-test planning for Nigeria (NGN). This workspace never claims CBN submission, admission, licensing, live testing, or settlement." },
  registry: { number: "07", title: "Counterparty registry", subtitle: "Record regulated payment, banking, stablecoin, FX, custody, KYC, screening, and reporting counterparties with evidence." },
  integrations: { number: "08", title: "Integration control", subtitle: "Register documented provider connections. Activation is reserved for verified secret-backed health checks, not a manual dashboard toggle." },
  governance: { number: "09", title: "Corridor governance", subtitle: "Version explicit Nigeria (NGN), Kenya (KES), and South Africa (ZAR) policy controls for CBN, CBK, and SARB review." },
  alerts: { number: "10", title: "Alert policy", subtitle: "Define owner-facing threshold, payment failure, compliance flag, and regulatory deadline alert policies without asserting delivery before the relevant channel is active." },
};

function moduleFromPath(path: string): ModuleKey {
  const part = path.split("/").filter(Boolean).at(-1) as ModuleKey;
  return part && part in moduleMeta ? part : "overview";
}

function cleanCount(value: unknown) {
  return String(value ?? "0");
}

function StatusBadge({ value }: { value: string | null | undefined }) {
  const normalized = value?.replaceAll("_", " ") ?? "unavailable";
  const tone = /active|verified|clear|completed|submitted|closed|allow/.test(normalized) ? "bg-black text-white" : /failed|blocked|critical|rejected|suspended/.test(normalized) ? "bg-[#e11919] text-white" : "bg-black/5 text-black";
  return <Badge className={`${tone} rounded-none border-0 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide`}>{normalized}</Badge>;
}

function Panel({ eyebrow, title, action, children }: { eyebrow: string; title: string; action?: ReactNode; children: ReactNode }) {
  return <section className="uf-panel min-w-0">
    <div className="flex items-start justify-between gap-4 border-b border-black/20 px-5 py-4">
      <div><p className="uf-kicker">{eyebrow}</p><h2 className="mt-1 text-lg font-black tracking-[-0.045em] uppercase">{title}</h2></div>
      {action}
    </div>
    {children}
  </section>;
}

function Empty({ title, detail }: { title: string; detail: string }) {
  return <div className="px-5 py-10"><p className="text-base font-bold">{title}</p><p className="mt-2 max-w-xl text-sm leading-6 text-black/55">{detail}</p></div>;
}

function TableShell({ children }: { children: ReactNode }) { return <div className="overflow-x-auto">{children}</div>; }

function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="grid gap-1.5"><span className="text-[10px] font-black uppercase tracking-[0.14em] text-black/50">{label}</span>{children}</label>; }

function CorridorSelect({ value, onValueChange }: { value: string; onValueChange: (value: string) => void }) {
  return <Select value={value} onValueChange={onValueChange}><SelectTrigger className="rounded-none border-black/25"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="NIGERIA_NGN">Nigeria (NGN)</SelectItem><SelectItem value="KENYA_KES">Kenya (KES)</SelectItem><SelectItem value="SOUTH_AFRICA_ZAR">South Africa (ZAR)</SelectItem></SelectContent></Select>;
}

export default function Home() {
  const { user } = useAuth();
  const [location, setLocation] = useLocation();
  const module = moduleFromPath(location);
  const meta = moduleMeta[module];
  const utils = trpc.useUtils();
  const overview = trpc.postgres.dashboardSnapshot.useQuery();
  const postgresCutover = trpc.postgres.cutoverReadiness.useQuery();
  const counterparties = trpc.postgres.counterparties.useQuery();
  const counterpartyAuthorizations = trpc.postgres.counterpartyAuthorizations.useQuery();
  const postgresCounterpartyRisks = trpc.postgres.counterpartyRiskAssessments.useQuery();
  const integrations = trpc.postgres.integrationConnections.useQuery();
  // Credential state is administrator-only, so the query is not issued at all
  // for other roles rather than being issued and discarded.
  const credentialStatus = trpc.postgres.integrationCredentialStatus.useQuery(undefined, { enabled: canConfigureCredentials(user?.role) });
  // The audit trail is read for one connection at a time. Loading every
  // connection's history at once would be a large read that no operator asked
  // for; the question is always about a specific provider.
  const [auditConnectionId, setAuditConnectionId] = useState("");
  const [trendWindow, setTrendWindow] = useState(60);
  const serviceTrendSamples = trpc.postgres.serviceHealthHistory.useQuery({ sinceMinutes: trendWindow });
  const serviceAvailability = trpc.postgres.serviceAvailabilitySummary.useQuery({ sinceMinutes: trendWindow });
  const serviceHealthSlo = trpc.postgres.serviceHealthSlo.useQuery({ sinceMinutes: trendWindow });
  const credentialAuditTrail = trpc.postgres.integrationCredentialAuditTrail.useQuery(
    { integrationConnectionId: auditConnectionId },
    { enabled: canConfigureCredentials(user?.role) && auditConnectionId !== "" },
  );
  // Service health polls on an interval. Thirty seconds is frequent enough to
  // be useful during an incident without turning the dashboard into a load
  // generator against the services it is observing.
  const serviceStatus = trpc.postgres.serviceStatus.useQuery(undefined, { refetchInterval: 30_000, refetchOnWindowFocus: true });
  const policies = trpc.postgres.corridorPolicies.useQuery();
  const customers = trpc.postgres.customers.useQuery();
  const beneficiaries = trpc.postgres.beneficiaries.useQuery();
  const liquidity = trpc.postgres.liquidityPositions.useQuery();
  const markets = trpc.postgres.marketObservations.useQuery();
  const rateLocks = trpc.postgres.rateLocks.useQuery();
  const postgresComplianceCases = trpc.postgres.complianceCases.useQuery();
  const postgresSarStrFilings = trpc.postgres.sarStrFilings.useQuery();
  const postgresKycDocuments = trpc.postgres.kycDocuments.useQuery();
  const postgresCustomers = trpc.postgres.customers.useQuery();
  const postgresBeneficiaries = trpc.postgres.beneficiaries.useQuery();
  const postgresCounterparties = trpc.postgres.counterparties.useQuery();
  const postgresLegalEntities = trpc.postgres.legalEntities.useQuery();
  const postgresCounterpartyAuthorizations = trpc.postgres.counterpartyAuthorizations.useQuery();
  const postgresCounterpartyOnboardings = trpc.postgres.counterpartyOnboardings.useQuery();
  const reports = trpc.postgres.regulatoryReports.useQuery();
  const postgresReports = trpc.postgres.regulatoryReports.useQuery();
  const deadlines = trpc.postgres.regulatoryDeadlines.useQuery();
  const alerts = trpc.postgres.alertPolicies.useQuery();
  const documentAnalysisJobs = trpc.postgres.documentAnalysisJobs.useQuery();
  const documentAnalysisEvidence = trpc.postgres.documentAnalysisEvidence.useQuery();
  const treasuryRecommendations = trpc.postgres.treasuryRecommendations.useQuery();
  const treasuryBufferPolicies = trpc.postgres.treasuryBufferPolicies.useQuery();
  const pgPaymentOrders = trpc.postgres.paymentOrders.useQuery();
  const pgPaymentLegs = trpc.postgres.paymentLegs.useQuery();
  const reviewerDecisions = trpc.postgres.reviewerDecisions.useQuery();
  const [composer, setComposer] = useState<string | null>(null);
  const canAdmin = user?.role === "admin";

  const refresh = async () => { await Promise.all([utils.postgres.dashboardSnapshot.invalidate(), utils.postgres.legalEntities.invalidate(), utils.postgres.counterparties.invalidate(), utils.postgres.counterpartyAuthorizations.invalidate(), utils.postgres.counterpartyRiskAssessments.invalidate(), utils.postgres.counterpartyOnboardings.invalidate(), utils.postgres.integrationConnections.invalidate(), utils.postgres.corridorPolicies.invalidate(), utils.postgres.customers.invalidate(), utils.postgres.beneficiaries.invalidate(), utils.postgres.liquidityPositions.invalidate(), utils.postgres.marketObservations.invalidate(), utils.postgres.rateLocks.invalidate(), utils.postgres.paymentOrders.invalidate(), utils.postgres.paymentLegs.invalidate(), utils.postgres.complianceCases.invalidate(), utils.postgres.sarStrFilings.invalidate(), utils.postgres.kycDocuments.invalidate(), utils.postgres.regulatoryReports.invalidate(), utils.postgres.regulatoryDeadlines.invalidate(), utils.postgres.alertPolicies.invalidate(), utils.postgres.documentAnalysisJobs.invalidate(), utils.postgres.documentAnalysisEvidence.invalidate(), utils.postgres.reviewerDecisions.invalidate()]); };
  const onSuccess = async (message: string) => { toast.success(message); setComposer(null); await refresh(); };

  const createCounterparty = trpc.postgres.createCounterparty.useMutation({ onSuccess: () => onSuccess("Canonical PostgreSQL counterparty recorded"), onError: error => toast.error(error.message) });

  // Provider credential configuration and verified activation. Each refreshes
  // the credential list so the resulting state — including a recorded failure —
  // is visible immediately rather than after a manual reload.
  const refreshCredentials = async () => {
    await utils.postgres.integrationCredentialStatus.invalidate();
    // The audit trail is invalidated with the state it describes; leaving it
    // stale would show a connection as changed while its history claims
    // otherwise, which is exactly the contradiction an audit view must not
    // present.
    await utils.postgres.integrationCredentialAuditTrail.invalidate();
  };
  const configureCredential = trpc.postgres.configureIntegrationCredential.useMutation({
    onSuccess: async () => { toast.success("Credential reference recorded. The integration remains inactive until a health check succeeds."); await refreshCredentials(); },
    onError: error => toast.error(error.message),
  });
  const activateIntegration = trpc.postgres.activateIntegrationConnection.useMutation({
    onSuccess: async result => {
      // A failed health check is a successful *request* that produced a refusal,
      // so it is reported as a failure to the operator rather than as success.
      if (result.healthCheckPassed) toast.success("Provider health check succeeded; the integration is now active.");
      else toast.error(`Activation refused: ${result.detail}`);
      await refreshCredentials();
    },
    onError: error => toast.error(error.message),
  });
  const suspendIntegration = trpc.postgres.suspendIntegrationConnection.useMutation({
    onSuccess: async () => { toast.success("Integration suspended."); await refreshCredentials(); },
    onError: error => toast.error(error.message),
  });
  const createCounterpartyAuthorization = trpc.postgres.createCounterpartyAuthorization.useMutation({ onSuccess: () => onSuccess("Canonical PostgreSQL licence evidence recorded"), onError: error => toast.error(error.message) });
  const transitionCounterpartyAuthorization = trpc.postgres.transitionCounterpartyAuthorization.useMutation({ onSuccess: () => onSuccess("Canonical PostgreSQL licence lifecycle updated"), onError: error => toast.error(error.message) });
  const createCounterpartyOnboarding = trpc.postgres.createCounterpartyOnboarding.useMutation({ onSuccess: () => onSuccess("Counterparty legal-review lifecycle recorded"), onError: error => toast.error(error.message) });
  const decideCounterpartyOnboarding = trpc.postgres.decideCounterpartyOnboardingGate.useMutation({ onSuccess: () => onSuccess("Independent onboarding decision recorded"), onError: error => toast.error(error.message) });
  const decideTechnicalOnboarding = trpc.postgres.decideTechnicalOnboardingGate.useMutation({ onSuccess: () => onSuccess("Technical-readiness decision recorded"), onError: error => toast.error(error.message) });
  const decideTreasuryPilotOnboarding = trpc.postgres.decideTreasuryPilotOnboardingGate.useMutation({ onSuccess: () => onSuccess("Treasury pilot decision recorded"), onError: error => toast.error(error.message) });
  const beginCounterpartyRecertification = trpc.postgres.beginCounterpartyRecertification.useMutation({ onSuccess: () => onSuccess("Counterparty recertification cycle started"), onError: error => toast.error(error.message) });
  const createIntegration = trpc.postgres.createIntegrationConnection.useMutation({ onSuccess: () => onSuccess("Integration connection recorded in an unconfigured state"), onError: error => toast.error(error.message) });
  const createPolicy = trpc.postgres.createCorridorPolicy.useMutation({ onSuccess: () => onSuccess("Corridor policy version created"), onError: error => toast.error(error.message) });
  const recordLiquidity = trpc.postgres.recordLiquidityPosition.useMutation({ onSuccess: () => onSuccess("Liquidity evidence recorded"), onError: error => toast.error(error.message) });
  const createTreasuryRecommendation = trpc.postgres.createTreasuryRecommendation.useMutation({ onSuccess: () => { onSuccess("Rebalancing recommendation proposed from reconciled evidence"); void utils.postgres.treasuryRecommendations.invalidate(); }, onError: error => toast.error(error.message) });
  const decideTreasuryRecommendation = trpc.postgres.decideTreasuryRecommendation.useMutation({ onSuccess: () => { onSuccess("Independent treasury decision recorded"); void utils.postgres.treasuryRecommendations.invalidate(); }, onError: error => toast.error(error.message) });
  const createPaymentOrder = trpc.postgres.createPaymentOrder.useMutation({ onSuccess: () => { onSuccess("Payment order drafted from a live rate lock"); void utils.postgres.paymentOrders.invalidate(); }, onError: error => toast.error(error.message) });
  const transitionPaymentOrder = trpc.postgres.transitionPaymentOrder.useMutation({ onSuccess: () => { onSuccess("Payment order control transition recorded"); void utils.postgres.paymentOrders.invalidate(); }, onError: error => toast.error(error.message) });
  const expireRateLocks = trpc.postgres.expireRateLocks.useMutation({ onSuccess: result => { onSuccess(`Rate-lock expiry evaluated: ${result.expiredCount} expired`); void utils.postgres.rateLocks.invalidate(); }, onError: error => toast.error(error.message) });
  const createPaymentLeg = trpc.postgres.createPaymentLeg.useMutation({ onSuccess: () => { onSuccess("Payment leg added against an authorised counterparty"); void utils.postgres.paymentLegs.invalidate(); }, onError: error => toast.error(error.message) });
  const transitionPaymentLeg = trpc.postgres.transitionPaymentLeg.useMutation({ onSuccess: () => { onSuccess("Payment leg control transition recorded"); void utils.postgres.paymentLegs.invalidate(); }, onError: error => toast.error(error.message) });
  const createRateLock = trpc.postgres.createRateLock.useMutation({ onSuccess: () => onSuccess("Rate lock created from the selected source observation"), onError: error => toast.error(error.message) });
  const cancelRateLock = trpc.postgres.cancelRateLock.useMutation({ onSuccess: () => onSuccess("Rate lock cancelled with immutable activity evidence"), onError: error => toast.error(error.message) });
  const createPostgresCustomer = trpc.postgres.createCustomer.useMutation({ onSuccess: () => onSuccess("Canonical PostgreSQL customer record created"), onError: error => toast.error(error.message) });
  const registerLegalEntity = trpc.postgres.registerLegalEntity.useMutation({ onSuccess: () => { void utils.postgres.legalEntities.invalidate(); onSuccess("Legal entity registered; it is now selectable in CBN dossier, IMTO readiness, and regulatory report forms"); }, onError: error => toast.error(error.message) });
  const activeVerificationConsents = trpc.postgres.activeVerificationConsents.useQuery();
  const analysisReadyDocuments = trpc.postgres.analysisReadyDocuments.useQuery();
  const createDocumentAnalysisJob = trpc.postgres.createDocumentAnalysisJob.useMutation({ onSuccess: () => { void refresh(); onSuccess("Analysis job recorded with server-derived model provenance; evidence remains review-required"); }, onError: error => toast.error(error.message) });
  const createVerificationConsent = trpc.postgres.createVerificationConsent.useMutation({ onSuccess: () => { void refresh(); onSuccess("Verification consent recorded; document analysis is now permitted within the consented scope"); }, onError: error => toast.error(error.message) });
  const disposeComplianceCase = trpc.postgres.disposeComplianceCase.useMutation({ onSuccess: () => { void refresh(); onSuccess("Compliance-case disposition recorded with its attributable rationale"); }, onError: error => toast.error(error.message) });
  const createCase = trpc.postgres.createComplianceCase.useMutation({ onSuccess: () => onSuccess("Canonical PostgreSQL compliance case recorded"), onError: error => toast.error(error.message) });
  const createSarStrFiling = trpc.postgres.createSarStrFiling.useMutation({ onSuccess: () => onSuccess("Canonical PostgreSQL SAR/STR filing draft recorded"), onError: error => toast.error(error.message) });
  const transitionSarStrFiling = trpc.postgres.transitionSarStrFiling.useMutation({ onSuccess: () => onSuccess("SAR/STR lifecycle updated with immutable audit evidence"), onError: error => toast.error(error.message) });
  const updateKycDocumentReview = trpc.postgres.updateKycDocumentReview.useMutation({ onSuccess: () => onSuccess("KYC document review lifecycle updated with immutable audit evidence"), onError: error => toast.error(error.message) });
  const createKycDocumentUploadIntent = trpc.postgres.createKycDocumentUploadIntent.useMutation({ onError: error => toast.error(error.message) });
  const finalizeKycDocumentUpload = trpc.postgres.finalizeKycDocumentUpload.useMutation({ onError: error => toast.error(error.message) });
  const createReport = trpc.postgres.createRegulatoryReport.useMutation({ onSuccess: () => onSuccess("Regulatory report pack created as draft"), onError: error => toast.error(error.message) });
  const createPostgresReport = trpc.postgres.createRegulatoryReport.useMutation({ onSuccess: () => onSuccess("Canonical PostgreSQL report draft created"), onError: error => toast.error(error.message) });
  const transitionPostgresReport = trpc.postgres.transitionRegulatoryReport.useMutation({ onSuccess: () => onSuccess("PostgreSQL report workflow updated with immutable activity evidence"), onError: error => toast.error(error.message) });
  const createDeadline = trpc.postgres.createRegulatoryDeadline.useMutation({ onSuccess: () => onSuccess("Regulatory deadline recorded"), onError: error => toast.error(error.message) });
  const createAlert = trpc.postgres.createAlertPolicy.useMutation({ onSuccess: () => onSuccess("Alert policy created"), onError: error => toast.error(error.message) });
  const evaluateDeadlines = trpc.postgres.evaluateRegulatoryDeadlines.useMutation({ onSuccess: result => toast.success(`Evaluated ${result.evaluated} deadlines; ${result.reminded} reminder(s) issued`), onError: error => toast.error(error.message) });
  const createReviewerDecision = trpc.postgres.createReviewerDecision.useMutation({ onSuccess: () => onSuccess("Reviewer decision recorded with immutable PostgreSQL activity evidence"), onError: error => toast.error(error.message) });

  const counts = useMemo(() => ({ counterparty: overview.data?.counterpartyCounts.reduce((sum, row) => sum + Number(row.count), 0) ?? 0, integration: overview.data?.integrationCounts.reduce((sum, row) => sum + Number(row.count), 0) ?? 0, payment: overview.data?.paymentCounts.reduce((sum, row) => sum + Number(row.count), 0) ?? 0, case: overview.data?.caseCounts.reduce((sum, row) => sum + Number(row.count), 0) ?? 0 }), [overview.data]);
  const onboardingSignals = useMemo(() => ({
    counterparties: counts.counterparty,
    integrations: counts.integration,
    customers: postgresCustomers.data?.length ?? 0,
    consents: activeVerificationConsents.data?.length ?? 0,
    documents: postgresKycDocuments.data?.length ?? 0,
    liquidityPositions: liquidity.data?.length ?? 0,
    marketObservations: markets.data?.length ?? 0,
    paymentOrders: counts.payment,
    complianceCases: counts.case,
    reports: postgresReports.data?.length ?? 0,
    auditEvents: overview.data?.latestEvents.length ?? 0,
  }), [counts, postgresCustomers.data, activeVerificationConsents.data, postgresKycDocuments.data, liquidity.data, markets.data, postgresReports.data, overview.data]);

  const actionAllowed = (kind: string) => canOpenConsoleComposer(user?.role, kind as Parameters<typeof canOpenConsoleComposer>[1]);
  const openComposer = (kind: string) => {
    if (!actionAllowed(kind)) {
      toast.error("Your assigned role does not permit this operational action.");
      return;
    }
    setComposer(kind);
  };
  // Every privileged module action renders through one regression-covered
  // component so the visible surface and the role policy cannot diverge.
  const moduleActions = (target: ConsoleModule, disabledActions: ComposerAction[] = []) => (
    <ConsoleModuleActions role={user?.role as OperatorRole | undefined} module={target} disabledActions={disabledActions} onOpen={action => openComposer(action)} />
  );

  return <DashboardLayout><div className="min-h-full">
    <header className="border-b border-black/20 bg-white px-5 py-4 sm:px-8">
      <div className="mx-auto flex max-w-[1600px] items-end justify-between gap-6"><div className="flex items-end gap-4"><span className="flex h-12 w-12 items-center justify-center bg-[#e11919] text-2xl font-black text-white">{meta.number}</span><div><p className="uf-kicker">UmojaFlowOS / Africa-linked cross-border payments</p><h1 className="uf-title text-3xl sm:text-4xl">{meta.title}</h1></div></div><div className="hidden text-right md:block"><p className="uf-kicker">System claim status</p><p className="mt-1 text-sm font-bold">Source-honest / provider-gated</p></div></div>
    </header>
    <main className="mx-auto max-w-[1600px] px-5 py-6 sm:px-8"><p className="mb-6 max-w-4xl text-sm leading-6 text-black/65">{meta.subtitle}</p>
      {module === "overview" && <div className="grid gap-5 xl:grid-cols-[1.25fr_0.75fr]">
        <div className="xl:col-span-2"><StakeholderPortal role={user?.role as OperatorRole | undefined} onNavigate={target => setLocation(`/console/${target}`)} /></div>
        <div className="grid gap-5 sm:grid-cols-2"><Metric title="Registered counterparties" value={counts.counterparty} detail="Actual registry records only" /><Metric title="Configured integrations" value={counts.integration} detail="Activation requires a verified health check" /><Metric title="Payment orders" value={counts.payment} detail="Final settlement evidence is distinct from draft state" /><Metric title="Compliance cases" value={counts.case} detail="Open, reviewed, escalated, reported, and closed cases" /></div>
        <Panel eyebrow="Activation guard" title="Live-capability boundary"><div className="space-y-0"><Guard title="Records store readiness" detail={postgresCutover.isLoading ? "Checking the platform's record store." : postgresCutover.data?.ready ? `All ${postgresCutover.data.presentTableCount} required record types are present and validated in this environment. Moving to production, and switching live services across, remain separate approvals.` : `The record store is not ready. Missing: ${postgresCutover.data?.missingTables.join(", ") ?? "readiness could not be determined"}.`} /><Guard title="Payment execution" detail="Unavailable until an authorised, credential-verified provider is connected and a policy decision is recorded." /><Guard title="Market observations" detail="Accepted only from an active integration with source timestamps and references." /><Guard title="Regulatory submission" detail="Requires a verified official submission channel and submission reference." /></div></Panel>
        <div className="xl:col-span-2"><Panel eyebrow="Authority and infrastructure" title="Governed control posture"><GovernedControlPosture /></Panel></div>
        <div className="xl:col-span-2"><StakeholderOnboardingWorkspace role={user?.role as OperatorRole | undefined} signals={onboardingSignals} onNavigate={target => setLocation(`/${target}`)} /></div>
        <Panel eyebrow="Audit trail" title="Latest attributable activity"><ActivityList events={overview.data?.latestEvents ?? []} loading={overview.isLoading} /></Panel>
      </div>}
      {module === "registry" && <div className="grid gap-5 xl:grid-cols-[1fr_1.45fr]"><Panel eyebrow="Action" title="Counterparty and licence evidence" action={moduleActions("registry")}>{composer === "counterparty" ? <CounterpartyForm pending={createCounterparty.isPending} submit={createCounterparty.mutate} /> : composer === "authorization" ? <CounterpartyAuthorizationForm pending={createCounterpartyAuthorization.isPending} counterparties={postgresCounterparties.data ?? []} submit={createCounterpartyAuthorization.mutate} error={createCounterpartyAuthorization.error?.message ?? null} /> : <Empty title="Licence evidence requires administrator access" detail="Administrators may register a licensed PSP, correspondent bank, stablecoin provider, FX liquidity provider, custody provider, KYC provider, sanctions provider, chain analytics provider, notification provider, or regulatory-submission provider and attach source-backed licence evidence." />}</Panel><div className="grid gap-5"><Panel eyebrow="Lifecycle" title="Counterparty onboarding and recertification"><CounterpartyOnboardingControls role={user?.role as OperatorRole | undefined} counterparties={postgresCounterparties.data ?? []} rows={postgresCounterpartyOnboardings.data ?? []} loading={postgresCounterpartyOnboardings.isLoading} createPending={createCounterpartyOnboarding.isPending} decisionPending={decideCounterpartyOnboarding.isPending || decideTechnicalOnboarding.isPending || decideTreasuryPilotOnboarding.isPending} recertificationPending={beginCounterpartyRecertification.isPending} error={createCounterpartyOnboarding.error?.message ?? decideCounterpartyOnboarding.error?.message ?? decideTechnicalOnboarding.error?.message ?? decideTreasuryPilotOnboarding.error?.message ?? beginCounterpartyRecertification.error?.message ?? null} create={createCounterpartyOnboarding.mutate} decideLegal={decideCounterpartyOnboarding.mutate} decideTechnical={decideTechnicalOnboarding.mutate} decidePilot={decideTreasuryPilotOnboarding.mutate} beginRecertification={beginCounterpartyRecertification.mutate} /></Panel><Panel eyebrow="Registry" title="Registered counterparties"><CounterpartyTable rows={postgresCounterparties.data ?? []} loading={postgresCounterparties.isLoading} /></Panel><Panel eyebrow="Licence register" title="Counterparty licence authorisations"><CounterpartyAuthorizationTable rows={postgresCounterpartyAuthorizations.data ?? []} loading={postgresCounterpartyAuthorizations.isLoading} canManage={canAdmin} pending={transitionCounterpartyAuthorization.isPending} transition={(authorizationId, status) => transitionCounterpartyAuthorization.mutate({ authorizationId, status })} /></Panel><Panel eyebrow="PostgreSQL control ledger" title="Counterparty risk reviews"><CounterpartyRiskTable rows={postgresCounterpartyRisks.data ?? []} loading={postgresCounterpartyRisks.isLoading} /></Panel></div></div>}
      {module === "registry" && <Panel eyebrow="Foundational registry" title="Legal entities" action={canAdmin ? <Button className="rounded-none bg-[#e11919] text-xs font-black uppercase hover:bg-black" onClick={() => setComposer("legal-entity")}>New legal entity</Button> : null}>{composer === "legal-entity" ? <LegalEntityRegistrationForm pending={registerLegalEntity.isPending} submit={registerLegalEntity.mutate} error={registerLegalEntity.error?.message ?? null} /> : <div className="grid gap-2 p-5">{postgresLegalEntities.isLoading ? <p className="text-sm text-black/55">Loading legal entities…</p> : (postgresLegalEntities.data ?? []).length === 0 ? <Empty title="No legal entity registered" detail="CBN Cohort 2 dossiers, IMTO readiness profiles, and regulatory reports all attach to a canonical legal entity. Register one to unblock those forms." /> : <div className="grid gap-2">{(postgresLegalEntities.data ?? []).map(entity => <div key={entity.id} className="grid grid-cols-[1fr_auto] items-center gap-3 border border-black/10 px-3 py-2 text-sm"><span className="font-bold">{entity.legalName}</span><span className="text-xs uppercase tracking-wide text-black/50">{entity.jurisdiction}</span></div>)}</div>}</div>}</Panel>}
      {module === "integrations" && <div className="grid gap-5 xl:grid-cols-[1fr_1.45fr]"><Panel eyebrow="Action" title="Document provider connection" action={moduleActions("integrations")}>{composer === "integration" ? <IntegrationForm pending={createIntegration.isPending} counterparties={postgresCounterparties.data ?? []} submit={createIntegration.mutate} /> : <Empty title="No live connection represented" detail="Provider credentials must be supplied through protected deployment configuration. Creating this record does not activate a payment rail, FX rate, stablecoin market-data feed, KYC/KYB, sanctions, chain-analysis, notification, or reporting integration." />}</Panel><Panel eyebrow="Control register" title="Connection state"><IntegrationTable rows={integrations.data ?? []} loading={integrations.isLoading} /></Panel></div>}
      {module === "integrations" && <div className="mt-5 grid gap-5">
        <Panel eyebrow="Service health" title="Go, Rust, and Python runtime status">
          <ServiceStatusDashboard
            data={serviceStatus.data?.services}
            loading={serviceStatus.isLoading}
            isFetching={serviceStatus.isFetching}
            error={serviceStatus.error?.message ?? null}
            observedAt={serviceStatus.data?.observedAt}
            onRefresh={() => { void utils.postgres.serviceStatus.invalidate(); }}
          />
        </Panel>
        <Panel eyebrow="Trends" title="Service response and availability over time">
          <ServiceTrendCharts
            samples={serviceTrendSamples.data ?? []}
            availability={serviceAvailability.data ?? []}
            loading={serviceTrendSamples.isLoading || serviceAvailability.isLoading}
            windowMinutes={trendWindow}
            onWindowChange={setTrendWindow}
          />
        </Panel>
        <Panel eyebrow="Measured resilience" title="Availability SLO evidence">
          {serviceHealthSlo.isLoading ? <p className="text-sm text-black/60">Calculating from persisted samples.</p> : serviceHealthSlo.error ? <p className="text-sm text-red-700">SLO evidence could not be read: {serviceHealthSlo.error.message}</p> : <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">{(serviceHealthSlo.data ?? []).map(row => <div key={row.service} className="border border-black/15 bg-[#f7f6f2] p-4"><p className="uf-kicker">{row.service}</p><p className={`mt-2 text-sm font-black ${row.status === "within_target" ? "text-emerald-700" : row.status === "breach" ? "text-red-700" : "text-amber-700"}`}>{row.status.replaceAll("_", " ")}</p><p className="mt-2 text-xs leading-5 text-black/65">{row.observedAvailability === null ? "No observed availability" : `${(row.observedAvailability * 100).toFixed(3)}% observed`} · {row.samples}/{row.minimumSamples} samples</p><p className="mt-2 text-xs leading-5 text-black/55">{row.reason}</p></div>)}</div>}
        </Panel>
        {canConfigureCredentials(user?.role) ? <>
          <Panel eyebrow="Administrator action" title="Configure provider credential">
            <IntegrationCredentialForm
              connections={credentialStatus.data ?? []}
              pending={configureCredential.isPending}
              error={configureCredential.error?.message ?? null}
              submit={configureCredential.mutate}
            />
          </Panel>
          <Panel eyebrow="Activation" title="Credential state and verified activation">
            <div className="border-b border-black/10 px-5 py-3 text-xs leading-5 text-black/55">
              Activation contacts the provider with the credential named by the configured deployment secret. An integration
              becomes active only if that request succeeds; a rejected credential, an error response, a redirect, or an
              unreachable endpoint records an explicit failure and leaves the integration inactive.
            </div>
            <IntegrationCredentialTable
              rows={credentialStatus.data ?? []}
              loading={credentialStatus.isLoading}
              canManage
              activatePending={activateIntegration.isPending}
              suspendPending={suspendIntegration.isPending}
              activate={activateIntegration.mutate}
              suspend={suspendIntegration.mutate}
              activatingId={activateIntegration.variables?.integrationConnectionId ?? null}
            />
          </Panel>
          <Panel eyebrow="Audit" title="Credential change history">
            <div className="border-b border-black/10 px-5 py-3">
              <label className="grid gap-1.5">
                <span className="text-[10px] font-black uppercase tracking-[0.14em] text-black/50">Connection</span>
                <select
                  className="h-9 rounded-none border border-black/25 bg-white px-2 text-sm"
                  aria-label="Audit trail connection"
                  value={auditConnectionId}
                  onChange={event => setAuditConnectionId(event.target.value)}
                >
                  <option value="">Select a connection</option>
                  {(credentialStatus.data ?? []).map(row => (
                    <option key={row.id} value={row.id}>
                      {row.counterpartyLegalName} · {row.category}
                    </option>
                  ))}
                </select>
              </label>
            </div>
            <CredentialAuditTrail
              entries={credentialAuditTrail.data ?? []}
              loading={credentialAuditTrail.isLoading}
              connectionSelected={auditConnectionId !== ""}
            />
          </Panel>
        </> : <Panel eyebrow="Administrator action" title="Configure provider credential">
          <Empty title="Credential configuration is an administrator control" detail="Supplying the deployment secret that activates a provider adapter is restricted to administrators. This role may review connection state and service health." />
        </Panel>}
      </div>}
      {module === "governance" && <div className="grid gap-5 xl:grid-cols-[1fr_1.45fr]"><Panel eyebrow="Action" title="Version corridor policy" action={moduleActions("governance")}>{composer === "policy" ? <PolicyForm pending={createPolicy.isPending} submit={createPolicy.mutate} /> : <Empty title="Policy is a runtime gate" detail="A policy version must name the corridor, relevant regulator—CBN, CBK, or SARB—and source document. It is created pending review and cannot itself authorise a payment execution." />}</Panel><Panel eyebrow="Policy ledger" title="Corridor policy versions"><PolicyTable rows={policies.data ?? []} loading={policies.isLoading} /></Panel></div>}
      {module === "treasury" && <div className="grid gap-5 xl:grid-cols-[1fr_1.45fr]"><Panel eyebrow="Action" title="Record reconciled position" action={moduleActions("treasury")}>{composer === "liquidity" ? <LiquidityForm pending={recordLiquidity.isPending} submit={recordLiquidity.mutate} /> : <Empty title="No automatic balance is claimed" detail="Record a position only after reconciliation against its actual nostro, vostro, pre-funding, liquidity pool, or custody-wallet source reference." />}</Panel><div className="grid gap-5"><Panel eyebrow="Evidence ledger" title="Liquidity positions"><LiquidityTable rows={liquidity.data ?? []} loading={liquidity.isLoading} /></Panel><Panel eyebrow="Approved thresholds" title="Treasury buffer policies"><TreasuryBufferPolicyTable policies={treasuryBufferPolicies.data ?? []} loading={treasuryBufferPolicies.isLoading} /></Panel><Panel eyebrow="Rebalancing" title="Recommendations and independent approval">{canProposeRebalancing(user?.role) ? <TreasuryRecommendationForm policies={treasuryBufferPolicies.data ?? []} pending={createTreasuryRecommendation.isPending} submit={createTreasuryRecommendation.mutate} /> : <div className="px-5 py-6 text-sm leading-6 text-black/55">Only treasury operators may propose a rebalancing recommendation. This role may review recommendations and their approval evidence.</div>}<TreasuryRecommendationTable recommendations={treasuryRecommendations.data ?? []} loading={treasuryRecommendations.isLoading} role={user?.role} currentSubject={user?.openId} pending={decideTreasuryRecommendation.isPending} decide={decideTreasuryRecommendation.mutate} /></Panel></div></div>}
      {module === "markets" && <div className="grid gap-5 xl:grid-cols-[1fr_1.45fr]"><div className="grid gap-5"><Panel eyebrow="Action" title="Rate evidence and lock" action={moduleActions("markets", ["market", "rate-lock"])}>{canManageRateLocks(user?.role) ? <RateLockForm observations={markets.data ?? []} pending={createRateLock.isPending} submit={createRateLock.mutate} error={createRateLock.error?.message ?? null} /> : <p className="px-5 py-6 text-sm leading-6 text-black/55">Rate-lock creation is a treasury control. This role may review locks and their control evidence.</p>}</Panel></div><div className="grid gap-5"><Panel eyebrow="Rate evidence" title="Latest observations"><MarketTable rows={markets.data ?? []} loading={markets.isLoading} /></Panel><Panel eyebrow="Lock ledger" title="Source-derived rate locks"><RateLockTable rows={rateLocks.data ?? []} loading={rateLocks.isLoading} role={user?.role} pending={cancelRateLock.isPending} cancel={cancelRateLock.mutate} /></Panel></div></div>}
      {module === "payments" && <div className="grid gap-5 xl:grid-cols-[1fr_1.45fr]"><div className="grid gap-5"><Panel eyebrow="Controlled intake" title="Draft payment order">{canOperatePayments(user?.role) ? <PaymentOrderForm customers={postgresCustomers.data ?? []} beneficiaries={postgresBeneficiaries.data ?? []} rateLocks={rateLocks.data ?? []} pending={createPaymentOrder.isPending} submit={createPaymentOrder.mutate} /> : <div className="px-5 py-6 text-sm leading-6 text-black/55">Payment drafting is a treasury control. This role may review orders, legs, and their control evidence.</div>}</Panel><Panel eyebrow="Settlement path" title="Add payment leg">{canOperatePayments(user?.role) ? <PaymentLegForm orders={pgPaymentOrders.data ?? []} counterparties={postgresCounterparties.data ?? []} pending={createPaymentLeg.isPending} submit={createPaymentLeg.mutate} /> : <div className="px-5 py-6 text-sm leading-6 text-black/55">Payment-leg composition is a treasury control. This role may review legs and their control evidence.</div>}</Panel><Panel eyebrow="Rate discipline" title="Rate-lock expiry"><RateLockExpiryControl role={user?.role} pending={expireRateLocks.isPending} expire={() => expireRateLocks.mutate()} /></Panel></div><div className="grid gap-5"><Panel eyebrow="Workflow" title="Payment orders"><PaymentOrderLedger orders={pgPaymentOrders.data ?? []} loading={pgPaymentOrders.isLoading} role={user?.role} pending={transitionPaymentOrder.isPending} transition={transitionPaymentOrder.mutate} /></Panel><Panel eyebrow="Leg ledger" title="Payment legs"><PaymentLegLedger legs={pgPaymentLegs.data ?? []} loading={pgPaymentLegs.isLoading} role={user?.role} pending={transitionPaymentLeg.isPending} transition={transitionPaymentLeg.mutate} /></Panel></div></div>}
      {module === "compliance" && <div className="grid gap-5 xl:grid-cols-[1fr_1.45fr]"><div className="grid gap-5"><Panel eyebrow="Action" title="Evidence-based casework" action={moduleActions("compliance")}>{composer === "consent" ? <VerificationConsentForm canCapture={user?.role === "compliance_officer"} pending={createVerificationConsent.isPending} submit={createVerificationConsent.mutate} error={createVerificationConsent.error?.message ?? null} /> : composer === "analysis" ? <AnalysisJobSubmissionForm consents={activeVerificationConsents.data ?? []} documents={analysisReadyDocuments.data ?? []} canSubmit={user?.role === "compliance_officer"} pending={createDocumentAnalysisJob.isPending} submit={createDocumentAnalysisJob.mutate} error={createDocumentAnalysisJob.error?.message ?? null} /> : composer === "case" ? <ComplianceForm pending={createCase.isPending} submit={createCase.mutate} /> : composer === "kyc-document" ? <KycDocumentUploadForm customers={postgresCustomers.data ?? []} createIntent={createKycDocumentUploadIntent.mutateAsync} finalize={finalizeKycDocumentUpload.mutateAsync} onComplete={() => onSuccess("KYC document stored in protected object storage and recorded as canonical metadata")} /> : composer === "sar-str" ? <SarStrFilingForm pending={createSarStrFiling.isPending} cases={postgresComplianceCases.data ?? []} submit={createSarStrFiling.mutate} error={createSarStrFiling.error?.message ?? null} /> : <Empty title="Screening results are never invented" detail="Create a canonical case from a verified source reference, store authorised KYC evidence directly in protected object storage, or initiate a SAR/STR draft against a canonical case. Official filing submission remains unavailable unless a verified authorised channel produces an attributable submission reference." />}</Panel><Panel eyebrow="Lawful basis" title="Verification consent precedes analysis"><VerificationConsentForm canCapture={user?.role === "compliance_officer"} pending={createVerificationConsent.isPending} submit={createVerificationConsent.mutate} error={createVerificationConsent.error?.message ?? null} /></Panel><Panel eyebrow="KYC / KYB evidence boundary" title="Authorised document workflow"><KycEvidenceWorkspace role={user?.role} jobs={documentAnalysisJobs.data ?? []} evidence={documentAnalysisEvidence.data ?? []} decisions={reviewerDecisions.data ?? []} loadingEvidence={documentAnalysisEvidence.isLoading} loadingDecisions={reviewerDecisions.isLoading} pendingDecision={createReviewerDecision.isPending} submitDecision={createReviewerDecision.mutate} /></Panel></div><div className="grid gap-5"><Panel eyebrow="Casework" title="Compliance cases">{postgresComplianceCases.isLoading ? <div className="px-5 py-8 text-sm text-black/55">Loading compliance cases…</div> : <ComplianceCaseDispositionControls cases={postgresComplianceCases.data ?? []} canDispose={user?.role === "compliance_officer"} pending={disposeComplianceCase.isPending} dispose={disposeComplianceCase.mutate} />}</Panel><Panel eyebrow="SAR/STR ledger" title="SAR/STR filings"><SarStrFilingTable rows={postgresSarStrFilings.data ?? []} loading={postgresSarStrFilings.isLoading} canManage={canPerformConsoleAction(user?.role, "sar-str")} pending={transitionSarStrFiling.isPending} transition={transitionSarStrFiling.mutate} /></Panel><Panel eyebrow="KYC document review" title="Manual review lifecycle"><KycDocumentReviewTable rows={postgresKycDocuments.data ?? []} loading={postgresKycDocuments.isLoading} canReview={canPerformConsoleAction(user?.role, "case")} pending={updateKycDocumentReview.isPending} submit={updateKycDocumentReview.mutate} /></Panel><Panel eyebrow="Evidence register" title="KYC and KYB analysis jobs"><KycAnalysisJobTable jobs={documentAnalysisJobs.data ?? []} loading={documentAnalysisJobs.isLoading} /></Panel></div></div>}
      {module === "compliance" && (user?.role === "compliance_officer" || user?.role === "admin") && <Panel eyebrow="Canonical onboarding" title="Customer required for KYC/KYB evidence" action={<Button className="rounded-none bg-[#e11919] text-xs font-black uppercase hover:bg-black" onClick={() => setComposer("postgres-customer")}>New customer</Button>}>{composer === "postgres-customer" ? <PostgresCustomerOnboardingForm pending={createPostgresCustomer.isPending} submit={createPostgresCustomer.mutate} error={createPostgresCustomer.error?.message ?? null} /> : <Empty title="Create an evidence subject" detail="KYC/KYB document intake requires an existing canonical PostgreSQL customer. Recording this subject does not create a payment instruction or automated compliance disposition." />}</Panel>}
      {module === "reports" && <div className="grid gap-5 xl:grid-cols-[1fr_1.45fr]"><Panel eyebrow="Action" title="Report pack and deadline" action={<div className="flex flex-wrap justify-end gap-2">{moduleActions("reports")}{canPerformConsoleAction(user?.role, "report") ? <Button className="rounded-none bg-black text-xs font-black uppercase hover:bg-[#e11919]" onClick={() => setComposer("report-draft")}>Report draft</Button> : null}{canPerformConsoleAction(user?.role, "report") && postgresReports.data?.length ? <Button className="rounded-none bg-black text-xs font-black uppercase hover:bg-[#e11919]" onClick={() => setComposer("report-transition")}>Review workflow</Button> : null}</div>}>{composer === "report" ? <ReportForm legalEntities={postgresLegalEntities.data ?? []} pending={createReport.isPending} submit={createReport.mutate} /> : composer === "report-draft" ? <PostgresReportDraftForm pending={createPostgresReport.isPending} submit={createPostgresReport.mutate} error={createPostgresReport.error?.message ?? null} /> : composer === "deadline" ? <RegulatoryDeadlineForm pending={createDeadline.isPending} submit={createDeadline.mutate} error={createDeadline.error?.message ?? null} /> : composer === "report-transition" ? <PostgresReportTransitionForm rows={postgresReports.data ?? []} pending={transitionPostgresReport.isPending} submit={transitionPostgresReport.mutate} error={transitionPostgresReport.error?.message ?? null} /> : <Empty title="Submission is not inferred" detail="Create an auditable CBN, CBK, or SARB report draft and source-backed deadline. A record cannot be called submitted until a verified regulatory channel returns an attributable submission reference." />}</Panel><div className="grid gap-5"><Panel eyebrow="Reporting register" title="Report packs"><ReportTable rows={reports.data ?? []} loading={reports.isLoading} /></Panel><Panel eyebrow="Workflow record" title="Verified workflow evidence"><PostgresReportTable rows={postgresReports.data ?? []} loading={postgresReports.isLoading} /></Panel><Panel eyebrow="Deadline register" title="CBN, CBK, and SARB deadlines"><RegulatoryDeadlineTable rows={deadlines.data ?? []} loading={deadlines.isLoading} /></Panel></div></div>}
      {module === "sandbox" && <CbnSandboxWorkspace role={user?.role as OperatorRole | undefined} />}
      {module === "alerts" && <div className="grid gap-5 xl:grid-cols-[1fr_1.45fr]"><Panel eyebrow="Action" title="Define and evaluate policy" action={<div className="flex flex-wrap items-center justify-end gap-2">{moduleActions("alerts", evaluateDeadlines.isPending ? ["evaluate-deadlines"] : [])}</div>}>{composer === "alert" ? <AlertForm pending={createAlert.isPending} submit={createAlert.mutate} /> : <Empty title="Alert policy is not delivery evidence" detail="Policies are stored with the configured threshold. An administrator may evaluate deadline records; scheduled evaluation becomes available only after deployment. Owner delivery is contingent on the relevant source event." />}</Panel><Panel eyebrow="Alert ledger" title="Configured policies"><AlertTable rows={alerts.data ?? []} loading={alerts.isLoading} /></Panel></div>}
    </main>
  </div></DashboardLayout>;
}

function Metric({ title, value, detail }: { title: string; value: number; detail: string }) { return <div className="uf-panel min-h-48 p-5"><p className="uf-kicker">{title}</p><p className="uf-metric mt-8 text-6xl">{value}</p><p className="mt-4 text-xs leading-5 text-black/55">{detail}</p></div>; }
function Guard({ title, detail }: { title: string; detail: string }) { return <div className="border-b border-black/15 px-5 py-4 last:border-b-0"><div className="flex gap-3"><ShieldAlert className="mt-0.5 h-4 w-4 text-[#e11919]" /><div><p className="text-sm font-bold">{title}</p><p className="mt-1 text-xs leading-5 text-black/60">{detail}</p></div></div></div>; }
function ActivityList({ events, loading }: { events: Array<{ id: string; action: string; objectType: string; occurredAt: Date }>; loading: boolean }) { if (loading) return <Empty title="Loading activity" detail="Retrieving immutable control-plane activity records." />; if (!events.length) return <Empty title="No activity records yet" detail="Activity appears here only after a real operator action is performed through the platform." />; return <div className="divide-y divide-black/15">{events.map(event => <div className="flex items-start justify-between gap-4 px-5 py-3" key={event.id}><div><p className="text-sm font-bold">{event.action}</p><p className="mt-0.5 text-xs text-black/55">{event.objectType} / {new Date(event.occurredAt).toLocaleString()}</p></div><ArrowUpRight className="h-4 w-4 text-black/40" /></div>)}</div>; }
function DataLoading({ loading, empty, children }: { loading: boolean; empty: boolean; children: ReactNode }) { if (loading) return <Empty title="Loading verified records" detail="The platform is retrieving persisted operational records." />; if (empty) return <Empty title="No records exist" detail="No data is shown until an authorised operator creates or ingests a traceable record." />; return <>{children}</>; }
function CounterpartyTable({ rows, loading }: { rows: Array<{ id: string; legalName: string; counterpartyType: string; jurisdiction: string; createdAt: Date }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Legal entity</th><th className="px-4 py-3">Type</th><th className="px-4 py-3">Jurisdiction</th><th className="px-4 py-3">Recorded</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">{row.legalName}</td><td className="px-4 py-3"><StatusBadge value={row.counterpartyType} /></td><td className="px-4 py-3">{row.jurisdiction}</td><td className="px-4 py-3 text-black/55">{new Date(row.createdAt).toLocaleString()}</td></tr>)}</tbody></table></TableShell></DataLoading>; }
function CounterpartyRiskTable({ rows, loading }: { rows: Array<{ id: string; riskLevel: string; riskScore: string; reviewStatus: string; nextReviewAt: Date }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Risk level</th><th className="px-4 py-3">Score</th><th className="px-4 py-3">Review state</th><th className="px-4 py-3">Next review</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3"><StatusBadge value={row.riskLevel} /></td><td className="px-4 py-3">{row.riskScore}</td><td className="px-4 py-3"><StatusBadge value={row.reviewStatus} /></td><td className="px-4 py-3 text-black/55">{new Date(row.nextReviewAt).toLocaleString()}</td></tr>)}</tbody></table></TableShell></DataLoading>; }
// Shape matches the flat projection listPostgresIntegrationConnections actually returns.
// It previously declared a nested `integration` object the server has never emitted; the
// mismatch stayed invisible because this table had only ever rendered an empty list.
function IntegrationTable({ rows, loading }: { rows: Array<{ id: string; category: string; environment: string; state: string; counterpartyLegalName: string }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Counterparty</th><th className="px-4 py-3">Capability</th><th className="px-4 py-3">Environment</th><th className="px-4 py-3">State</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">{row.counterpartyLegalName}</td><td className="px-4 py-3">{row.category.replaceAll("_", " ")}</td><td className="px-4 py-3">{row.environment}</td><td className="px-4 py-3"><StatusBadge value={row.state} /></td></tr>)}</tbody></table></TableShell></DataLoading>; }
function PolicyTable({ rows, loading }: { rows: Array<{ id: number; corridor: string; regulator: string; policyVersion: string; activationStatus: string; requiresTravelRule: boolean }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Corridor</th><th className="px-4 py-3">Regulator</th><th className="px-4 py-3">Version</th><th className="px-4 py-3">Travel Rule</th><th className="px-4 py-3">Status</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">{row.corridor.replaceAll("_", " ")}</td><td className="px-4 py-3">{row.regulator}</td><td className="px-4 py-3">{row.policyVersion}</td><td className="px-4 py-3">{row.requiresTravelRule ? "Required" : "Not configured"}</td><td className="px-4 py-3"><StatusBadge value={row.activationStatus} /></td></tr>)}</tbody></table></TableShell></DataLoading>; }
function LiquidityTable({ rows, loading }: { rows: Array<{ id: string; corridor: string; currency: string; accountKind: string; availableAmount: string; reservedAmount: string; reconciledAt: Date }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Corridor</th><th className="px-4 py-3">Account</th><th className="px-4 py-3">Available</th><th className="px-4 py-3">Reserved</th><th className="px-4 py-3">Reconciled</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">{row.corridor.replaceAll("_", " ")} / {row.currency}</td><td className="px-4 py-3">{row.accountKind.replaceAll("_", " ")}</td><td className="px-4 py-3">{row.availableAmount}</td><td className="px-4 py-3">{row.reservedAmount}</td><td className="px-4 py-3">{new Date(row.reconciledAt).toLocaleString()}</td></tr>)}</tbody></table></TableShell></DataLoading>; }
function MarketTable({ rows, loading }: { rows: Array<{ id: string; baseAsset: string; quoteAsset: string; rate: string; observedAt: Date; sourceReference: string }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Pair</th><th className="px-4 py-3">Rate</th><th className="px-4 py-3">Observed</th><th className="px-4 py-3">Evidence</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">{row.baseAsset} / {row.quoteAsset}</td><td className="px-4 py-3">{row.rate}</td><td className="px-4 py-3">{new Date(row.observedAt).toLocaleString()}</td><td className="px-4 py-3"><a className="underline decoration-black/30 underline-offset-4" href={row.sourceReference} target="_blank" rel="noreferrer">Source</a></td></tr>)}</tbody></table></TableShell></DataLoading>; }
function PaymentTable({ rows, loading }: { rows: Array<{ id: number; corridor: string; sourceCurrency: string; sourceAmount: string; targetCurrency: string; targetAmount: string | null; status: string; createdAt: Date }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Order</th><th className="px-4 py-3">Corridor</th><th className="px-4 py-3">Source</th><th className="px-4 py-3">Target</th><th className="px-4 py-3">State</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">#{row.id}</td><td className="px-4 py-3">{row.corridor.replaceAll("_", " ")}</td><td className="px-4 py-3">{row.sourceAmount} {row.sourceCurrency}</td><td className="px-4 py-3">{row.targetAmount ?? "—"} {row.targetCurrency}</td><td className="px-4 py-3"><StatusBadge value={row.status} /></td></tr>)}</tbody></table></TableShell></DataLoading>; }
function CaseTable({ rows, loading }: { rows: Array<{ id: string | number; caseType: string; status: string; severity: string; openedAt: Date; sourceReference: string }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Case</th><th className="px-4 py-3">Severity</th><th className="px-4 py-3">State</th><th className="px-4 py-3">Opened</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">{row.caseType.replaceAll("_", " ")}</td><td className="px-4 py-3"><StatusBadge value={row.severity} /></td><td className="px-4 py-3"><StatusBadge value={row.status} /></td><td className="px-4 py-3">{new Date(row.openedAt).toLocaleString()}</td></tr>)}</tbody></table></TableShell></DataLoading>; }
function ReportTable({ rows, loading }: { rows: Array<{ id: string; regulator: string; corridor: string; reportType: string; periodEnd: Date; status: string }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Regulator</th><th className="px-4 py-3">Corridor</th><th className="px-4 py-3">Report</th><th className="px-4 py-3">Period end</th><th className="px-4 py-3">State</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">{row.regulator}</td><td className="px-4 py-3">{row.corridor.replaceAll("_", " ")}</td><td className="px-4 py-3">{row.reportType}</td><td className="px-4 py-3">{new Date(row.periodEnd).toLocaleDateString()}</td><td className="px-4 py-3"><StatusBadge value={row.status} /></td></tr>)}</tbody></table></TableShell></DataLoading>; }
function PostgresReportTable({ rows, loading }: { rows: Array<{ id: string; regulator: string; corridor: string; reportType: string; periodEnd: Date; status: string; artifactUri: string | null; submissionReference: string | null }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Regulator</th><th className="px-4 py-3">Report</th><th className="px-4 py-3">State</th><th className="px-4 py-3">Evidence</th><th className="px-4 py-3">Reference</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">{row.regulator}</td><td className="px-4 py-3">{row.reportType}</td><td className="px-4 py-3"><StatusBadge value={row.status} /></td><td className="px-4 py-3">{row.artifactUri ? <a className="underline decoration-black/30 underline-offset-4" href={row.artifactUri} target="_blank" rel="noreferrer">Artifact</a> : "—"}</td><td className="px-4 py-3">{row.submissionReference ?? "—"}</td></tr>)}</tbody></table></TableShell></DataLoading>; }
function AlertTable({ rows, loading }: { rows: Array<{ id: number; alertType: string; corridor: string | null; enabled: boolean; threshold: unknown }>; loading: boolean }) { return <DataLoading loading={loading} empty={!rows.length}><TableShell><table className="w-full text-left text-xs"><thead className="border-b border-black/20 text-[10px] uppercase tracking-wider text-black/45"><tr><th className="px-5 py-3">Trigger</th><th className="px-4 py-3">Corridor</th><th className="px-4 py-3">Threshold</th><th className="px-4 py-3">State</th></tr></thead><tbody>{rows.map(row => <tr className="border-b border-black/10" key={row.id}><td className="px-5 py-3 font-bold">{row.alertType.replaceAll("_", " ")}</td><td className="px-4 py-3">{row.corridor?.replaceAll("_", " ") ?? "All corridors"}</td><td className="max-w-48 truncate px-4 py-3">{JSON.stringify(row.threshold)}</td><td className="px-4 py-3"><StatusBadge value={row.enabled ? "enabled" : "disabled"} /></td></tr>)}</tbody></table></TableShell></DataLoading>; }

function FormShell({ onSubmit, children, pending }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void; children: ReactNode; pending: boolean }) { return <form className="grid gap-4 p-5" onSubmit={onSubmit}>{children}<Button disabled={pending} type="submit" className="rounded-none bg-[#e11919] font-black uppercase tracking-wide hover:bg-black">{pending ? "Saving…" : "Save attributable record"}</Button></form>; }
function CounterpartyForm({ submit, pending }: { submit: (input: { legalName: string; counterpartyType: "licensed_psp" | "correspondent_bank" | "stablecoin_provider" | "fx_liquidity_provider" | "custody_provider" | "kyc_provider" | "sanctions_provider" | "chain_analytics_provider" | "notification_provider" | "regulatory_submission_provider"; jurisdiction: string }) => void; pending: boolean }) { const [kind, setKind] = useState<"licensed_psp" | "correspondent_bank" | "stablecoin_provider" | "fx_liquidity_provider" | "custody_provider" | "kyc_provider" | "sanctions_provider" | "chain_analytics_provider" | "notification_provider" | "regulatory_submission_provider">("licensed_psp"); return <FormShell pending={pending} onSubmit={e => { e.preventDefault(); const data = new FormData(e.currentTarget); submit({ legalName: String(data.get("legalName")), counterpartyType: kind, jurisdiction: String(data.get("jurisdiction")) }); }}><Field label="Legal name"><Input name="legalName" required className="rounded-none" /></Field><Field label="Type"><Select value={kind} onValueChange={value => setKind(value as typeof kind)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{["licensed_psp", "correspondent_bank", "stablecoin_provider", "fx_liquidity_provider", "custody_provider", "kyc_provider", "sanctions_provider", "chain_analytics_provider", "notification_provider", "regulatory_submission_provider"].map(value => <SelectItem key={value} value={value}>{value.replaceAll("_", " ")}</SelectItem>)}</SelectContent></Select></Field><Field label="Jurisdiction"><Input name="jurisdiction" required placeholder="Nigeria, Kenya, South Africa, or provider jurisdiction" className="rounded-none" /></Field></FormShell>; }
function IntegrationForm({ counterparties, submit, pending }: { counterparties: Array<{ id: string; legalName: string }>; submit: (input: { counterpartyId: string; category: "payment_rail" | "fx_rate" | "stablecoin_market_data" | "kyc_kyb" | "sanctions" | "chain_analytics" | "notification" | "regulatory_submission"; environment: "sandbox" | "production"; documentationUrl: string }) => void; pending: boolean }) { const [category, setCategory] = useState<"payment_rail" | "fx_rate" | "stablecoin_market_data" | "kyc_kyb" | "sanctions" | "chain_analytics" | "notification" | "regulatory_submission">("payment_rail"); const [environment, setEnvironment] = useState<"sandbox" | "production">("sandbox"); if (!counterparties.length) return <Empty title="Counterparty required" detail="Create the legal counterparty record before documenting an integration connection." />; return <FormShell pending={pending} onSubmit={e => { e.preventDefault(); const data = new FormData(e.currentTarget); submit({ counterpartyId: String(data.get("counterpartyId")), category, environment, documentationUrl: String(data.get("documentationUrl")) }); }}><Field label="Counterparty"><Select name="counterpartyId" defaultValue={String(counterparties[0].id)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{counterparties.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.legalName}</SelectItem>)}</SelectContent></Select></Field><Field label="Capability"><Select value={category} onValueChange={value => setCategory(value as typeof category)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{["payment_rail", "fx_rate", "stablecoin_market_data", "kyc_kyb", "sanctions", "chain_analytics", "notification", "regulatory_submission"].map(value => <SelectItem key={value} value={value}>{value.replaceAll("_", " ")}</SelectItem>)}</SelectContent></Select></Field><Field label="Environment"><Select value={environment} onValueChange={value => setEnvironment(value as typeof environment)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="sandbox">Sandbox</SelectItem><SelectItem value="production">Production</SelectItem></SelectContent></Select></Field><Field label="Official documentation URL"><Input name="documentationUrl" required type="url" className="rounded-none" /></Field><p className="text-[11px] leading-5 text-black/55">Provider credentials are never entered here. A connection is recorded unconfigured and activation requires credentials supplied through protected deployment configuration plus a verified health check.</p></FormShell>; }
function PolicyForm({ submit, pending }: { submit: (input: { corridor: "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR"; regulator: "CBN" | "CBK" | "SARB"; policyVersion: string; effectiveFrom: Date; effectiveTo?: Date; requiresTravelRule: boolean; requiresAuthorisedFxIntermediary: boolean; policyDocumentUri: string }) => void; pending: boolean }) { const [corridor, setCorridor] = useState("NIGERIA_NGN"); const [regulator, setRegulator] = useState<"CBN" | "CBK" | "SARB">("CBN"); return <FormShell pending={pending} onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); submit({ corridor: corridor as "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR", regulator, policyVersion: String(d.get("policyVersion")), effectiveFrom: new Date(String(d.get("effectiveFrom"))), requiresTravelRule: d.get("requiresTravelRule") === "on", requiresAuthorisedFxIntermediary: d.get("requiresAuthorisedFxIntermediary") === "on", policyDocumentUri: String(d.get("policyDocumentUrl")) }); }}><Field label="Corridor"><CorridorSelect value={corridor} onValueChange={setCorridor} /></Field><Field label="Regulator"><Select value={regulator} onValueChange={value => setRegulator(value as typeof regulator)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="CBN">CBN</SelectItem><SelectItem value="CBK">CBK</SelectItem><SelectItem value="SARB">SARB</SelectItem></SelectContent></Select></Field><Field label="Policy version"><Input name="policyVersion" required placeholder="YYYY.MM.DD" className="rounded-none" /></Field><Field label="Effective from"><Input name="effectiveFrom" required type="date" className="rounded-none" /></Field><Field label="Primary policy source URL"><Input name="policyDocumentUrl" required type="url" className="rounded-none" /></Field><label className="flex gap-2 text-xs"><input name="requiresTravelRule" type="checkbox" /> Require Travel Rule data</label><label className="flex gap-2 text-xs"><input name="requiresAuthorisedFxIntermediary" type="checkbox" defaultChecked /> Require authorised FX intermediary</label></FormShell>; }
function LiquidityForm({ submit, pending }: { submit: (input: { corridor: "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR"; currency: "NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT"; accountKind: "liquidity_pool" | "nostro" | "vostro" | "prefunding" | "custody_wallet"; accountReference: string; availableAmount: string; reservedAmount: string; sourceReference: string; reconciledAt: Date }) => void; pending: boolean }) { const [corridor, setCorridor] = useState("NIGERIA_NGN"); const [currency, setCurrency] = useState<"NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT">("NGN"); const [accountKind, setAccountKind] = useState<"liquidity_pool" | "nostro" | "vostro" | "prefunding" | "custody_wallet">("liquidity_pool"); return <FormShell pending={pending} onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); submit({ corridor: corridor as "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR", currency, accountKind, accountReference: String(d.get("accountReference")), availableAmount: String(d.get("availableAmount")), reservedAmount: String(d.get("reservedAmount") || "0"), sourceReference: String(d.get("sourceReference")), reconciledAt: new Date(String(d.get("reconciledAt"))) }); }}><Field label="Corridor"><CorridorSelect value={corridor} onValueChange={setCorridor} /></Field><Field label="Currency"><Select value={currency} onValueChange={value => setCurrency(value as typeof currency)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{["NGN", "KES", "ZAR", "USD", "USDC", "USDT"].map(value => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Field label="Account kind"><Select value={accountKind} onValueChange={value => setAccountKind(value as typeof accountKind)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{["liquidity_pool", "nostro", "vostro", "prefunding", "custody_wallet"].map(value => <SelectItem key={value} value={value}>{value.replaceAll("_", " ")}</SelectItem>)}</SelectContent></Select></Field><Field label="Account reference"><Input name="accountReference" required className="rounded-none" /></Field><Field label="Available amount"><Input name="availableAmount" required inputMode="decimal" className="rounded-none" /></Field><Field label="Reserved amount"><Input name="reservedAmount" inputMode="decimal" defaultValue="0" className="rounded-none" /></Field><Field label="Reconciliation source reference"><Input name="sourceReference" required className="rounded-none" /></Field><Field label="Reconciled at"><Input name="reconciledAt" required type="datetime-local" className="rounded-none" /></Field></FormShell>; }
function MarketForm({ integrations, submit, pending }: { integrations: Array<{ integration: { id: number; state: string; category: string }; counterpartyName: string }>; submit: (input: { integrationConnectionId: number; baseAsset: "NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT"; quoteAsset: "NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT"; rate: string; observedAt: Date; sourceReference: string }) => void; pending: boolean }) { const active = integrations.filter(item => item.integration.state === "active" && ["fx_rate", "stablecoin_market_data"].includes(item.integration.category)); const [baseAsset, setBaseAsset] = useState<"NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT">("NGN"); const [quoteAsset, setQuoteAsset] = useState<"NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT">("USD"); if (!active.length) return <Empty title="Verified market-data connection required" detail="No active FX-rate or stablecoin-market-data integration exists. The system will not accept a manually asserted rate or USDC/USDT peg observation." />; return <FormShell pending={pending} onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); submit({ integrationConnectionId: Number(d.get("integrationConnectionId")), baseAsset, quoteAsset, rate: String(d.get("rate")), observedAt: new Date(String(d.get("observedAt"))), sourceReference: String(d.get("sourceReference")) }); }}><Field label="Verified integration"><Select name="integrationConnectionId" defaultValue={String(active[0].integration.id)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{active.map(item => <SelectItem key={item.integration.id} value={String(item.integration.id)}>{item.counterpartyName} / {item.integration.category}</SelectItem>)}</SelectContent></Select></Field><Field label="Base asset"><AssetSelect value={baseAsset} onValueChange={value => setBaseAsset(value as typeof baseAsset)} /></Field><Field label="Quote asset"><AssetSelect value={quoteAsset} onValueChange={value => setQuoteAsset(value as typeof quoteAsset)} /></Field><Field label="Observed rate"><Input name="rate" required inputMode="decimal" className="rounded-none" /></Field><Field label="Observed at"><Input name="observedAt" required type="datetime-local" className="rounded-none" /></Field><Field label="Source reference URL"><Input name="sourceReference" required type="url" className="rounded-none" /></Field></FormShell>; }
function AssetSelect({ value, onValueChange }: { value: string; onValueChange: (value: string) => void }) { return <Select value={value} onValueChange={onValueChange}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{["NGN", "KES", "ZAR", "USD", "USDC", "USDT"].map(asset => <SelectItem key={asset} value={asset}>{asset}</SelectItem>)}</SelectContent></Select>; }
function PaymentForm({ customers, beneficiaries, submit, pending }: { customers: Array<{ id: number; legalName: string }>; beneficiaries: Array<{ id: number; legalName: string }>; submit: (input: { idempotencyKey: string; customerId: number; beneficiaryId: number; corridor: "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR"; sourceCurrency: "NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT"; sourceAmount: string; targetCurrency: "NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT"; targetAmount?: string }) => void; pending: boolean }) { const [corridor, setCorridor] = useState("NIGERIA_NGN"); const [sourceCurrency, setSourceCurrency] = useState<"NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT">("NGN"); const [targetCurrency, setTargetCurrency] = useState<"NGN" | "KES" | "ZAR" | "USD" | "USDC" | "USDT">("USD"); if (!customers.length || !beneficiaries.length) return <Empty title="Customer and beneficiary required" detail="Create real customer and beneficiary records before drafting a payment order." />; return <FormShell pending={pending} onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); submit({ idempotencyKey: crypto.randomUUID(), customerId: Number(d.get("customerId")), beneficiaryId: Number(d.get("beneficiaryId")), corridor: corridor as "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR", sourceCurrency, sourceAmount: String(d.get("sourceAmount")), targetCurrency, targetAmount: String(d.get("targetAmount")) || undefined }); }}><Field label="Customer"><Select name="customerId" defaultValue={String(customers[0].id)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{customers.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.legalName}</SelectItem>)}</SelectContent></Select></Field><Field label="Beneficiary"><Select name="beneficiaryId" defaultValue={String(beneficiaries[0].id)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{beneficiaries.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.legalName}</SelectItem>)}</SelectContent></Select></Field><Field label="Corridor"><CorridorSelect value={corridor} onValueChange={setCorridor} /></Field><Field label="Source currency"><AssetSelect value={sourceCurrency} onValueChange={value => setSourceCurrency(value as typeof sourceCurrency)} /></Field><Field label="Source amount"><Input name="sourceAmount" required inputMode="decimal" className="rounded-none" /></Field><Field label="Target currency"><AssetSelect value={targetCurrency} onValueChange={value => setTargetCurrency(value as typeof targetCurrency)} /></Field><Field label="Target amount (if known)"><Input name="targetAmount" inputMode="decimal" className="rounded-none" /></Field></FormShell>; }
function ComplianceForm({ submit, pending }: { submit: (input: { caseType: "kyc" | "sanctions" | "transaction_monitoring" | "travel_rule" | "counterparty" | "sar_str"; severity: "low" | "medium" | "high" | "critical"; sourceReference: string; decisionReason?: string }) => void; pending: boolean }) { const [caseType, setCaseType] = useState<"kyc" | "sanctions" | "transaction_monitoring" | "travel_rule" | "counterparty" | "sar_str">("sanctions"); const [severity, setSeverity] = useState<"low" | "medium" | "high" | "critical">("high"); return <FormShell pending={pending} onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); submit({ caseType, severity, sourceReference: String(d.get("sourceReference")), decisionReason: String(d.get("decisionReason")) || undefined }); }}><Field label="Case type"><Select value={caseType} onValueChange={value => setCaseType(value as typeof caseType)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{["kyc", "sanctions", "transaction_monitoring", "travel_rule", "counterparty", "sar_str"].map(value => <SelectItem key={value} value={value}>{value.replaceAll("_", " ")}</SelectItem>)}</SelectContent></Select></Field><Field label="Severity"><Select value={severity} onValueChange={value => setSeverity(value as typeof severity)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{["low", "medium", "high", "critical"].map(value => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Field label="Verified source reference URL"><Input name="sourceReference" required type="url" className="rounded-none" /></Field><Field label="Review note"><Input name="decisionReason" className="rounded-none" /></Field></FormShell>; }
function ReportForm({ legalEntities, submit, pending }: { legalEntities: Array<{ id: string; legalName: string }>; submit: (input: { regulator: "CBN" | "CBK" | "SARB"; corridor: "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR"; reportType: string; periodStart: Date; periodEnd: Date; legalEntityId: string }) => void; pending: boolean }) { const [corridor, setCorridor] = useState("NIGERIA_NGN"); const [regulator, setRegulator] = useState<"CBN" | "CBK" | "SARB">("CBN"); if (!legalEntities.length) return <Empty title="Authorised legal entity required" detail="Register the reporting legal entity in the canonical registry before drafting a regulator report pack." />; return <FormShell pending={pending} onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); submit({ regulator, corridor: corridor as "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR", reportType: String(d.get("reportType")), periodStart: new Date(String(d.get("periodStart"))), periodEnd: new Date(String(d.get("periodEnd"))), legalEntityId: String(d.get("legalEntityId")) }); }}><Field label="Regulator"><Select value={regulator} onValueChange={value => setRegulator(value as typeof regulator)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="CBN">CBN</SelectItem><SelectItem value="CBK">CBK</SelectItem><SelectItem value="SARB">SARB</SelectItem></SelectContent></Select></Field><Field label="Corridor"><CorridorSelect value={corridor} onValueChange={setCorridor} /></Field><Field label="Reporting legal entity"><Select name="legalEntityId" defaultValue={legalEntities[0].id}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{legalEntities.map(entity => <SelectItem key={entity.id} value={entity.id}>{entity.legalName}</SelectItem>)}</SelectContent></Select></Field><Field label="Report type"><Input name="reportType" required placeholder="e.g. cross-border payment report" className="rounded-none" /></Field><Field label="Period start"><Input name="periodStart" required type="date" className="rounded-none" /></Field><Field label="Period end"><Input name="periodEnd" required type="date" className="rounded-none" /></Field></FormShell>; }
function AlertForm({ submit, pending }: { submit: (input: { alertType: "liquidity_threshold" | "payment_failure" | "compliance_flag" | "regulatory_deadline"; corridor?: "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR"; threshold: Record<string, unknown>; enabled: boolean }) => void; pending: boolean }) { const [alertType, setAlertType] = useState<"liquidity_threshold" | "payment_failure" | "compliance_flag" | "regulatory_deadline">("liquidity_threshold"); const [corridor, setCorridor] = useState("NIGERIA_NGN"); return <FormShell pending={pending} onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); const minimum = String(d.get("minimum") ?? "").trim(); if (!/^\d+(\.\d+)?$/.test(minimum)) { toast.error("Enter the minimum balance as a number, for example 5000."); return; } submit({ alertType, corridor: corridor as "NIGERIA_NGN" | "KENYA_KES" | "SOUTH_AFRICA_ZAR", threshold: { minimum }, enabled: true }); }}><Field label="Alert type"><Select value={alertType} onValueChange={value => setAlertType(value as typeof alertType)}><SelectTrigger className="rounded-none"><SelectValue /></SelectTrigger><SelectContent>{["liquidity_threshold", "payment_failure", "compliance_flag", "regulatory_deadline"].map(value => <SelectItem key={value} value={value}>{value.replaceAll("_", " ")}</SelectItem>)}</SelectContent></Select></Field><Field label="Corridor"><CorridorSelect value={corridor} onValueChange={setCorridor} /></Field><Field label="Minimum balance to hold"><Input name="minimum" required inputMode="decimal" placeholder="5000" className="rounded-none" /></Field></FormShell>; }
